<script setup lang="ts">
import {watch} from 'vue'
import AuthorField from './AuthorField.vue'
import type {Opening,CustomField} from './types'
const props=defineProps<{config:{openings:Opening[];playerFields:CustomField[];formTitle?:string};openingId:string;values:Record<string,string|number|boolean|string[]|null>}>(),emit=defineEmits<{'update:openingId':[value:string];'update:values':[value:Record<string,string|number|boolean|string[]|null>];choose:[opening:Opening]}>()
function choose(id:string){emit('update:openingId',id);const opening=props.config.openings.find(o=>o.id===id);if(opening)emit('choose',opening)}
function set(id:string,value:string|number|boolean|string[]|null){emit('update:values',{...props.values,[id]:value})}
watch(()=>props.config,config=>{const values={...props.values};for(const field of config.playerFields)if(field.type!=='random'&&!(field.id in values))values[field.id]=field.defaultValue;for(const field of config.playerFields)if(field.type==='random')delete values[field.id];emit('update:values',values);choose(config.openings.some(o=>o.id===props.openingId)?props.openingId:config.openings[0]?.id||'')},{immediate:true})
</script>
<template><section aria-label="作者开局配置"><h2>选择故事开局</h2><label>作者开局<select aria-label="作者开局" :value="openingId" @change="choose(($event.target as HTMLSelectElement).value)"><option v-for="opening in config.openings" :key="opening.id" :value="opening.id">{{opening.title}}</option></select></label><p>{{config.openings.find(o=>o.id===openingId)?.description}}</p><h3 v-if="config.playerFields.length">{{config.formTitle||'你的开局信息'}}</h3><div class="author-start-grid"><template v-for="(field,i) in config.playerFields" :key="field.id"><h4 v-if="field.group&&field.group!==config.playerFields[i-1]?.group" class="author-start-group">{{field.group}}</h4><AuthorField :field="field" :model-value="field.id in values?values[field.id]:field.defaultValue" @update:model-value="set(field.id,$event)"/></template></div></section></template>
<style scoped>.author-start-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.author-start-group{grid-column:span 2}.author-start-grid>:deep(.author-runtime-field){grid-column:span 2}.author-start-grid>:deep(.half){grid-column:span 1}@media(max-width:600px){.author-start-grid{grid-template-columns:1fr}.author-start-grid>:deep(.author-runtime-field),.author-start-grid>:deep(.half){grid-column:span 1}}</style>
